<?php
namespace App\Controller;
use App\Catalog\CatalogMetrics; use App\Entity\LibraryEntry; use App\Entity\Series; use App\Entity\User; use Doctrine\ORM\EntityManagerInterface; use Symfony\Bundle\FrameworkBundle\Controller\AbstractController; use Symfony\Component\HttpFoundation\JsonResponse; use Symfony\Component\HttpFoundation\Request; use Symfony\Component\HttpFoundation\Response; use Symfony\Component\Routing\Attribute\Route;
#[Route('/admin')]
class AdminController extends AbstractController {
 #[Route('/utilisateurs',name:'app_admin_users',methods:['GET'])] public function users(EntityManagerInterface $em):Response{$this->denyAccessUnlessGranted('ROLE_ADMIN');return $this->render('admin/users.html.twig',['users'=>$em->getRepository(User::class)->findBy([],['email'=>'ASC'])]);}
 #[Route('/utilisateurs/{id}/role',name:'app_admin_user_role',methods:['POST'])] public function role(User $user,Request $request,EntityManagerInterface $em):Response{$this->denyAccessUnlessGranted('ROLE_ADMIN');if(!$this->isCsrfTokenValid('admin_role_'.$user->getId(),(string)$request->request->get('_token')))throw $this->createAccessDeniedException();if($user===$this->getUser()){$this->addFlash('error','Vous ne pouvez pas modifier votre propre rôle.');}else{$roles=$user->getRoles();$admin=in_array('ROLE_ADMIN',$roles,true);$user->setRoles($admin?array_values(array_diff($roles,['ROLE_ADMIN'])):[...$roles,'ROLE_ADMIN']);$em->flush();$this->addFlash('success',$admin?'Droits administrateur retirés.':'Droits administrateur accordés.');}return $this->redirectToRoute('app_admin_users');}
 #[Route('/statistiques',name:'app_admin_stats',methods:['GET'])] public function stats():Response{$this->denyAccessUnlessGranted('ROLE_ADMIN');return $this->render('admin/stats.html.twig');}
 #[Route('/api/statistiques',name:'app_admin_stats_api',methods:['GET'])] public function api(EntityManagerInterface $em,CatalogMetrics $metrics):JsonResponse{$this->denyAccessUnlessGranted('ROLE_ADMIN');$users=$em->getRepository(User::class)->count([]);$admins=count(array_filter($em->getRepository(User::class)->findAll(),fn(User $user)=>in_array('ROLE_ADMIN',$user->getRoles(),true)));return $this->json(['users'=>$users,'admins'=>$admins,'series'=>$em->getRepository(Series::class)->count([]),'libraryEntries'=>$em->getRepository(LibraryEntry::class)->count([]),'traffic'=>$metrics->totals()]);}
}
